INSERT INTO public.vision_ateliers (user_id, contenu) VALUES ('0d5a0000-0000-4000-8000-000000000001', $j${"pourquoi": "Nous croyons qu'un intérieur fait sur mesure change la façon dont on vit chez soi", "comment": "Grâce à un atelier intégré, des plans validés en 3D et un seul interlocuteur du premier rendez-vous à la pose", "quoi": "Nous dessinons, fabriquons et posons des cuisines, dressings et agencements en bois massif", "cibles": [{"id": "c1", "nom": "Propriétaires de maisons anciennes", "type": "B2C", "segment": "Rénovation", "priorite": "+++", "notes": "Murs irréguliers, besoin de vrai sur-mesure"}, {"id": "c2", "nom": "Architectes d'intérieur", "type": "B2B", "segment": "Prescription", "priorite": "++", "notes": "Six à dix chantiers par an chacun"}, {"id": "c3", "nom": "Promoteurs de petits collectifs", "type": "B2B", "segment": "Neuf", "priorite": "+", "notes": "Volume, mais marges serrées"}], "acteurs": [{"id": "a1", "nom": "Scierie Morel", "portee": "Externe", "role": "Fournisseur", "pouvoir": "Élevé", "interet": "Élevé", "notes": "Chêne et noyer, 30 ans de relation"}, {"id": "a2", "nom": "Cabinet Atelier Nord", "portee": "Externe", "role": "Prescripteur", "pouvoir": "Élevé", "interet": "Moyen", "notes": "Architectes, 4 chantiers en 2025"}, {"id": "a3", "nom": "Banque Populaire", "portee": "Externe", "role": "Financeur", "pouvoir": "Moyen", "interet": "Moyen", "notes": "Crédit-bail de la nouvelle CNC"}, {"id": "a4", "nom": "Équipe de pose", "portee": "Interne", "role": "Équipe", "pouvoir": "Moyen", "interet": "Élevé", "notes": "Quatre compagnons"}], "probleme": "des cuisines en kit qui ne rentrent pas dans leurs murs de travers, des artisans injoignables et des chantiers qui s'éternisent faute de coordination", "projection": {"ca": "1,4 M€ de chiffre d'affaires", "clients": "12 architectes partenaires réguliers", "offre": "une gamme cuisine, une gamme dressing", "organisation": "un chef d'atelier et deux équipes de pose", "rythme": "plus de chantier le samedi", "energie": "déléguer le chiffrage", "viePerso": "trois semaines de vacances en août", "limites": "pas de chantier au-delà de 60 km"}, "valeurs": [{"nom": "Parole tenue", "traduction": "Une date de pose annoncée est une date tenue"}, {"nom": "Travail bien fini", "traduction": "Aucun meuble ne quitte l'atelier sans contrôle"}, {"nom": "Transmission", "traduction": "Chaque compagnon forme un apprenti"}], "vision": "Devenir l'atelier d'agencement de référence de la métropole, celui que les architectes recommandent parce qu'il tient ses délais et soigne chaque finition.", "objectifs": [{"intitule": "Atteindre 1,4 M€ de chiffre d'affaires", "pourquoi": "C'est le seuil qui finance la deuxième équipe de pose", "mesure": "1 400 k€ facturés au 31/12", "type": "Business"}, {"intitule": "Travailler avec 12 architectes d'intérieur réguliers", "pourquoi": "Leurs chantiers sont mieux préparés et mieux payés", "mesure": "12 contrats annuels signés", "type": "Business"}, {"intitule": "Ne plus travailler le samedi", "pourquoi": "Tenir sur la durée et garder l'envie", "mesure": "Zéro samedi sur chantier au dernier trimestre", "type": "Personnel"}]}$j$::jsonb);
INSERT INTO public.ateliers (user_id, pilier, contenu) VALUES ('0d5a0000-0000-4000-8000-000000000001', 'fit', $j${"offreNom": "Cuisine sur mesure posée en trois semaines", "offreValeur": "Avoir une cuisine qui épouse exactement la pièce, sans vides ni joints de travers, et qui est posée à la date promise", "offreLimite": "Ce n'est pas de la cuisine en kit, ni de la pose de meubles achetés ailleurs", "offrePitch": "Je dessine, fabrique et pose des cuisines sur mesure en bois, en trois semaines, avec un seul interlocuteur du plan à la pose", "lisibilite": "oui", "diffAvantage": "Un atelier intégré : nous fabriquons nous-mêmes, donc nous tenons les délais et ajustons au millimètre sur place", "diffClients": "parfois", "diffMieux": "Là où les cuisinistes vendent des modules standards, nous partons des murs réels du client et des plans de l'architecte", "diffDurable": "moyen", "concurrents": [{"id": "c1", "nom": "Cuisiniste de grande enseigne", "type": "Direct", "bien": "Prix d'appel, showroom, financement", "avantage": "Vrai sur-mesure, finitions bois massif"}, {"id": "c2", "nom": "Menuisier indépendant du secteur", "type": "Direct", "bien": "Proximité, prix bas", "avantage": "Capacité de production, respect des délais"}, {"id": "c3", "nom": "Garder la cuisine actuelle", "type": "Statu quo", "bien": "Aucune dépense", "avantage": "Valeur ajoutée au bien, confort au quotidien"}], "concRaison": "Parce que nous tenons nos délais et que l'architecte n'a qu'un seul interlocuteur, de la prise de cotes à la pose", "concSans": "Ils passent par une grande enseigne et font reprendre les ajustements par un bricoleur, ou repoussent le projet", "sigVerbatim": "« C'est la première fois qu'un artisan finit le jour prévu. » — Julien R., architecte d'intérieur", "sigBouche": "oui", "sigRetention": "35% des clients reviennent pour un second agencement", "sigOrganique": "70% des chantiers viennent du bouche-à-oreille", "sigNps": "4,9/5 sur 48 avis en ligne", "sigAutre": "Délai moyen entre devis et pose : 7 semaines", "sigDemande": "stable"}$j$::jsonb);
INSERT INTO public.ateliers (user_id, pilier, contenu) VALUES ('0d5a0000-0000-4000-8000-000000000001', 'finance', $j${"periode": "Année 2025", "revenus": [{"id": "r1", "source": "Cuisines sur mesure", "type": "proj", "montant": "620000", "tendance": "up"}, {"id": "r2", "source": "Dressings et rangements", "type": "proj", "montant": "310000", "tendance": "stab"}, {"id": "r3", "source": "Contrats d'agencement avec des architectes", "type": "rec", "montant": "180000", "tendance": "up"}, {"id": "r4", "source": "Service après-vente et entretien", "type": "rec", "montant": "70000", "tendance": "stab"}], "obsRevenus": "Les cuisines font plus de la moitié du chiffre d'affaires, mais tout est au projet : les contrats avec les architectes sont la seule base récurrente, elle reste trop faible.", "variables": [{"id": "v1", "nature": "Bois, panneaux et quincaillerie", "montant": "330000", "maitrisable": "yes"}, {"id": "v2", "nature": "Sous-traitance des plans de travail en pierre", "montant": "95000", "maitrisable": "yes"}, {"id": "v3", "nature": "Commissions des apporteurs d'affaires", "montant": "20000", "maitrisable": "no"}], "fixes": [{"id": "f1", "nature": "Salaires et charges (12 personnes)", "montant": "480000", "categorie": "rh", "compressible": "no"}, {"id": "f2", "nature": "Loyer de l'atelier", "montant": "60000", "categorie": "loc", "compressible": "part"}, {"id": "f3", "nature": "Crédit-bail de la machine à commande numérique", "montant": "45000", "categorie": "tech", "compressible": "no"}, {"id": "f4", "nature": "Véhicules et carburant", "montant": "38000", "categorie": "adm", "compressible": "part"}, {"id": "f5", "nature": "Salons et communication", "montant": "22000", "categorie": "mkt", "compressible": "yes"}], "leviersMarge": "Acheter le chêne par lots à la scierie plutôt qu'au chantier, et facturer la pierre avec une vraie marge au lieu de la refacturer au prix coûtant.", "beCa": "1180000", "beCf": "645000", "beCv": "445000", "beTreso": "140000", "caCible": 1400000, "obsRentabilite": "Nous sommes au-dessus du point mort, mais avec une marge de sécurité faible et moins de deux mois de trésorerie : un trimestre creux suffirait à nous mettre en difficulté.", "decisions": [{"action": "Augmenter de 8% les devis cuisine à partir de septembre", "levier": "Pricing", "responsable": "Marc Durand", "delai": "30 jours", "impact": "+50 000€ de CA à volume égal"}, {"action": "Négocier l'achat du chêne par lots trimestriels avec la scierie Morel", "levier": "Réduction coûts", "responsable": "Chef d'atelier", "delai": "45 jours", "impact": "Économie estimée de 18 000€/an"}, {"action": "Proposer un contrat d'agencement annuel aux 8 architectes les plus actifs", "levier": "Modèle récurrent", "responsable": "Marc Durand", "delai": "90 jours", "impact": "+120 000€ de revenus récurrents"}], "engagement": "Je fais un point trésorerie chaque lundi matin avec la comptable, et je ne signe plus de chantier sans acompte de 40%."}$j$::jsonb);

