-- Vérification : doit renvoyer 1 compte, 1 abonnement « unlimited », 3 ateliers, 3 objectifs, 6 résultats clés, 7 actions, 2 bilans.
SELECT
  (SELECT count(*) FROM auth.users WHERE id = '0d5a0000-0000-4000-8000-000000000001') AS compte,
  (SELECT plan_type FROM public.subscriptions WHERE user_id = '0d5a0000-0000-4000-8000-000000000001') AS formule,
  (SELECT count(*) FROM public.vision_ateliers WHERE user_id = '0d5a0000-0000-4000-8000-000000000001') + (SELECT count(*) FROM public.ateliers WHERE user_id = '0d5a0000-0000-4000-8000-000000000001') AS ateliers,
  (SELECT count(*) FROM public.ambitions WHERE user_id = '0d5a0000-0000-4000-8000-000000000001') AS objectifs,
  (SELECT count(*) FROM public.quarterly_key_results r JOIN public.quarterly_objectives o ON o.id = r.objective_id WHERE o.user_id = '0d5a0000-0000-4000-8000-000000000001') AS resultats_cles,
  (SELECT count(*) FROM public.actions WHERE user_id = '0d5a0000-0000-4000-8000-000000000001') AS actions,
  (SELECT count(*) FROM public.diagnostics WHERE user_id = '0d5a0000-0000-4000-8000-000000000001') AS bilans;
